package vn.edu.eaut.lab8.repository; import vn.edu.eaut.lab8.model.*; import java.util.*; public class SinhVienRepository {private static final List<SinhVien>d=new ArrayList<>(List.of(new SinhVien(1,"SV001","Nguyễn Văn An","an@gmail.com","DCCNTT15.10.1"),new SinhVien(2,"SV002","Trần Thị Bình","binh@gmail.com","DCCNTT15.10.2")));private static int next=3;public List<SinhVien>findAll(){return d;}public void add(SinhVien x){x.setId(next++);d.add(x);}public SinhVien find(int id){return d.stream().filter(x->x.getId()==id).findFirst().orElse(null);}public void update(SinhVien x){for(int i=0;i<d.size();i++)if(d.get(i).getId()==x.getId()){d.set(i,x);return;}}public void delete(int id){d.removeIf(x->x.getId()==id);}}
